UPDATE A SET A.EMP_NO = B.EMP_NO, A.JOIN_DATE = B.JOIN_DATE, A.DEPT_CD = B.DEPT_CD, A.JOB_DUTY_CD = B.JOB_DUTY_CD, A.NAME = B.NAME, A.HP_NO = B.HP_NO, A.REMARKS = B.REMARKS FROM dbo.TAD_EMP A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.JOIN_DATE} AS JOIN_DATE, #{row.DEPT_CD} AS DEPT_CD, #{row.JOB_DUTY_CD} AS JOB_DUTY_CD, #{row.NAME} AS NAME, #{row.HP_NO} AS HP_NO, #{row.REMARKS} AS REMARKS
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO

UPDATE A SET A.STATUS = '100003' FROM dbo.TPM_USER A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO

UPDATE A SET A.RESIGN_DATE = B.RESIGN_DATE, A.RESIGN_REASON = B.RESIGN_REASON FROM dbo.TAD_EMP A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.RESIGN_DATE} AS RESIGN_DATE, #{row.RESIGN_REASON} AS RESIGN_REASON
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO

UPDATE A SET A.EMP_NO = B.EMP_NO, A.DEPT_CD = B.DEPT_CD, A.JOB_DUTY_CD = B.JOB_DUTY_CD, A.USER_NAME = B.NAME, A.HP_NO = B.HP_NO, A.PASSWD = ISNULL(RIGHT(B.HP_NO, 4), '1234') FROM dbo.TPM_USER A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.USER_ID} AS USER_ID, #{row.EMP_NO} AS EMP_NO, #{row.DEPT_CD} AS DEPT_CD, #{row.JOB_DUTY_CD} AS JOB_DUTY_CD, #{row.NAME} AS NAME, #{row.HP_NO} AS HP_NO,
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.USER_ID = B.USER_ID

UPDATE A SET A.LICENSE_CODE = B.LICENSE_CODE, A.LICENSE_NO = B.LICENSE_NO, A.LICENSE_NAME = dbo.getCode_nm(B.LICENSE_CODE) A.OPER_ORG = B.OPER_ORG, A.POSS_DT = B.POSS_DT, A.REMARKS = B.REMARKS FROM dbo.TAD_LICENSE A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.SEQ} AS SEQ, #{row.LICENSE_CODE} AS LICENSE_CODE, #{row.LICENSE_NO} AS LICENSE_NO, #{row.OPER_ORG} AS OPER_ORG, #{row.NAMEPOSS_DT} AS POSS_DT, #{row.REMARKS} AS REMARKS
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.SEQ = B.SEQ

