UPDATE A SET A.USE_YN = B.USE_YN, A.REG_DATE = CASE WHEN B.USE_YN = 'Y' THEN CONVERT(VARCHAR(8), GETDATE(), 112) ELSE A.REG_DATE END, A.END_DATE = CASE WHEN B.USE_YN = 'N' THEN CONVERT(VARCHAR(8), GETDATE(), 112) ELSE A.END_DATE END FROM dbo.THR_DEPT A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.DEPT_CD} AS DEPT_CD, #{row.USE_YN} AS USE_YN
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.DEPT_CD = B.DEPT_CD

UPDATE A SET A.USE_YN = B.USE_YN, A.REG_DATE = CASE WHEN B.USE_YN = 'Y' THEN CONVERT(VARCHAR(8), GETDATE(), 112) ELSE A.REG_DATE END, A.END_DATE = CASE WHEN B.USE_YN = 'N' THEN CONVERT(VARCHAR(8), GETDATE(), 112) ELSE A.END_DATE END FROM dbo.THR_JOB_DUTY A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.JOB_DUTY_CD} AS JOB_DUTY_CD, #{row.USE_YN} AS USE_YN
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.JOB_DUTY_CD = B.JOB_DUTY_CD

UPDATE A SET A.STATUS = '100001' FROM dbo.TPM_USER A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO

UPDATE A SET A.RESIGN_DATE = NULL, A.RESIGN_REASON = NULL FROM dbo.TAD_EMP A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO

mapper.select:
SELECT A.OFFICE_CODE AS OFFICE_CODE, A.EMP_NO AS EMP_NO, A.REG_SEQ AS REG_SEQ, A.REG_DATE AS REG_DATE, A.ABSENT_CD AS ABSENT_CD, E.ABSENT_NAME AS ABSENT_NAME, A.START_DATE AS START_DATE, A.END_DATE AS END_DATE, A.USE_DAY_CNT AS USE_DAY_CNT, A.DESCR AS DESCR, A.IDX AS IDX, B.NAME AS NAME, B.DEPT_CD AS DEPT_CD, B.JOB_DUTY_CD AS JOB_DUTY_CD, C.DEPT_NAME AS DEPT_NAME, D.JOB_DUTY_NAME AS JOB_DUTY_NAME, CASE WHEN NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NOT NULL AND B.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112) THEN '퇴사' WHEN (NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NULL OR B.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND B.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112) THEN '재직' ELSE ' ' END AS JOIN_YN FROM dbo.TAD_ABSENT AS A LEFT JOIN dbo.TAD_EMP AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO LEFT JOIN dbo.THR_DEPT AS C ON B.DEPT_CD = C.DEPT_CD AND C.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} LEFT JOIN dbo.THR_JOB_DUTY AS D ON B.JOB_DUTY_CD = D.JOB_DUTY_CD AND D.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} LEFT JOIN dbo.TAD_ABSENT_ITEM AS E ON A.ABSENT_CD = E.ABSENT_CD AND E.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND A.START_DATE >= #{START_DATE} AND A.END_DATE <= #{END_DATE}
AND A.START_DATE >= #{START_DATE}
AND A.END_DATE <= #{END_DATE}
AND (NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NULL OR B.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND B.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112)
AND NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NOT NULL AND B.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112)
AND B.EMP_NO = #{EMP_NO}
ORDER BY A.START_DATE DESC, A.END_DATE DESC

update.if:
UPDATE A SET A.REG_DATE = B.REG_DATE, A.ABSENT_CD = B.ABSENT_CD, A.START_DATE = B.START_DATE, A.END_DATE = B.END_DATE, A.USE_DAY_CNT = B.USE_DAY_CNT, A.DESCR = B.DESCR, A.IDX = B.IDX FROM dbo.TAD_ABSENT A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.REG_SEQ} AS REG_SEQ, #{row.REG_DATE} AS REG_DATE, #{row.ABSENT_CD} AS ABSENT_CD, #{row.START_DATE} AS START_DATE, #{row.END_DATE} AS END_DATE, #{row.USE_DAY_CNT} AS USE_DAY_CNT, #{row.DESCR} AS DESCR, #{row.IDX} AS IDX
) B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.REG_SEQ = B.REG_SEQ

mapper.delete:
DELETE FROM dbo.TAD_ABSENT WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.REG_SEQ} AS REG_SEQ
) AS temp WHERE temp.OFFICE_CODE = TAD_ABSENT.OFFICE_CODE AND temp.EMP_NO = TAD_ABSENT.EMP_NO AND temp.REG_SEQ = TAD_ABSENT.REG_SEQ )

mapper.select:
SELECT A.OFFICE_CODE AS OFFICE_CODE, A.EMP_NO AS EMP_NO, A.NAME AS NAME, A.DEPT_CD AS DEPT_CD, A.JOB_DUTY_CD AS JOB_DUTY_CD, CASE WHEN NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NOT NULL AND A.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112) THEN '퇴사' WHEN (NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NULL OR A.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND A.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112) THEN '재직' ELSE '' END AS STATUS, SUBSTRING(B.START_DATE, 1, 6) AS DATE, B.ABSENT_CD, SUM(B.USE_DAY_CNT) AS USE_DAY_CNT, C.DEPT_NAME, D.JOB_DUTY_NAME FROM dbo.TAD_EMP AS A LEFT JOIN dbo.TAD_ABSENT AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND (SUBSTRING(B.START_DATE, 1, 6) = #{DATE} OR B.START_DATE IS NULL) LEFT JOIN dbo.THR_DEPT AS C ON A.DEPT_CD = C.DEPT_CD AND C.OFFICE_CODE = A.OFFICE_CODE LEFT JOIN dbo.THR_JOB_DUTY AS D ON A.JOB_DUTY_CD = D.JOB_DUTY_CD AND D.OFFICE_CODE = A.OFFICE_CODE WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND (NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NULL OR SUBSTRING(A.RESIGN_DATE, 1, 6) >= #{DATE}) AND SUBSTRING(A.JOIN_DATE, 1, 6) <= #{DATE}
AND A.NAME LIKE '%' + #{NAME} + '%'
GROUP BY A.OFFICE_CODE, A.EMP_NO, A.NAME, A.DEPT_CD, A.JOB_DUTY_CD, CASE WHEN NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NOT NULL AND A.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112) THEN '퇴사' WHEN (NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NULL OR A.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND A.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112) THEN '재직' ELSE '' END, SUBSTRING(B.START_DATE, 1, 6), B.ABSENT_CD, C.DEPT_NAME, D.JOB_DUTY_NAME ORDER BY CONVERT(INT, A.EMP_NO);

update.if:
UPDATE A SET A.ABSENT_NAME = B.ABSENT_NAME, A.ABSENT_DESC = B.ABSENT_DESC, A.REG_DATE = B.REG_DATE, A.USE_YN = B.USE_YN, A.ORDER_SEQ = B.ORDER_SEQ FROM dbo.TAD_ABSENT_ITEM A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.ABSENT_CD} AS ABSENT_CD, #{row.ABSENT_NAME} AS ABSENT_NAME, #{row.ABSENT_DESC} AS ABSENT_DESC, #{row.REG_DATE} AS REG_DATE, #{row.USE_YN} AS USE_YN, #{row.ORDER_SEQ} AS ORDER_SEQ
) B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.ABSENT_CD = B.ABSENT_CD

mapper.delete:
DELETE FROM dbo.TAD_ABSENT_ITEM WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.ABSENT_CD} AS ABSENT_CD
) AS temp WHERE temp.OFFICE_CODE = TAD_ABSENT_ITEM.OFFICE_CODE AND temp.ABSENT_CD = TAD_ABSENT_ITEM.ABSENT_CD )
